function parseDepartures(values: string[]) {
  const tokens: Array<{ text: string; source: number }> = [];
  values.forEach((value, index) => value.split(',').map(part => part.trim()).filter(Boolean).forEach(text => tokens.push({ text, source: index })));
  const items: Array<{ time: string; place: string; index: number }> = [];
  let parts: string[] = [];
  let source = 0;
  for (const token of tokens) {
    const match = token.text.match(/(\d{1,2})[.:](\d{2})/);
    if (match) {
      const before = token.text.slice(0, match.index ?? 0).replace(/hod\.?\s*$/i, '').trim();
      if (before) parts.push(before);
      items.push({ time: `${String(match[1]).padStart(2, '0')}:${match[2]}`, place: parts.join(', ').replace(/\s+,/g, ',').replace(/hod\.?/gi, '').replace(/\s{2,}/g, ' ').trim(), index: token.source });
      parts = [];
      source = token.source;
    } else {
      parts.push(token.text.replace(/hod\.?/gi, ' ').trim());
    }
  }
  if (parts.length) items.push({ time: '', place: parts.join(', ').replace(/\s{2,}/g, ' ').trim(), index: source });
  return items.filter(point => point.place);
}
